using System.Data;using System.Data.Common;using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using AiCare.Domain;using AiCare.Infrastructure;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AiCare.Api;[ApiController][Authorize][Route("api/security/sessions")]
public sealed class SessionSecurityController(CareDbContext db):ControllerBase
{
 [HttpGet]public async Task<IActionResult> List(CancellationToken t){var user=CurrentUser();if(user is null)return Unauthorized();var current=CurrentSession();return Ok(await Rows("select id,device_name,ip_address,created_at,last_seen_at,expires_at,revoked_at,revocation_reason,compromise_detected_at from auth_sessions where user_id=@user and organization_id=@organization order by last_seen_at desc",c=>{Add(c,"user",user.Id);Add(c,"organization",user.OrganizationId??TenantDefaults.OrganizationId);},t,current));}
 [HttpPost("{id:guid}/revoke")]public async Task<IActionResult> Revoke(Guid id,RevokeSessionRequest r,CancellationToken t){var user=CurrentUser();if(user is null)return Unauthorized();if(string.IsNullOrWhiteSpace(r.Reason))return BadRequest(new{message="Revocation reason is required."});var n=await Exec("update auth_sessions set revoked_at=now(),revoked_by=@actor,revocation_reason=@reason where id=@id and user_id=@user and organization_id=@organization and revoked_at is null",c=>{Add(c,"id",id);Add(c,"user",user.Id);Add(c,"organization",user.OrganizationId??TenantDefaults.OrganizationId);Add(c,"actor",user.UserName);Add(c,"reason",r.Reason);},t);if(n==0)return NotFound();await Exec("update auth_refresh_tokens set revoked_at=now() where session_id=@id and revoked_at is null",c=>Add(c,"id",id),t);await Event(id,user,"Revoked",r.Reason,t);Audit("security.session_revoked",id,user);await db.SaveChangesAsync(t);return NoContent();}
 [HttpPost("revoke-all")]public async Task<IActionResult> RevokeAll(RevokeAllSessionsRequest r,CancellationToken t){var user=CurrentUser();if(user is null)return Unauthorized();if(string.IsNullOrWhiteSpace(r.Reason))return BadRequest(new{message="Revocation reason is required."});var current=CurrentSession();var ids=await Guids("select id from auth_sessions where user_id=@user and organization_id=@organization and revoked_at is null and (@preserve=false or id<>@current)",c=>{Add(c,"user",user.Id);Add(c,"organization",user.OrganizationId??TenantDefaults.OrganizationId);Add(c,"preserve",r.PreserveCurrent);Add(c,"current",current??Guid.Empty);},t);foreach(var id in ids){await Exec("update auth_sessions set revoked_at=now(),revoked_by=@actor,revocation_reason=@reason where id=@id;update auth_refresh_tokens set revoked_at=now() where session_id=@id and revoked_at is null",c=>{Add(c,"id",id);Add(c,"actor",user.UserName);Add(c,"reason",r.Reason);},t);await Event(id,user,"Revoked",r.Reason,t);}Audit("security.sessions_revoked_all",user.Id,user);await db.SaveChangesAsync(t);return Ok(new{revoked=ids.Count});}
 private async Task Event(Guid session,AppUser user,string type,string detail,CancellationToken t)=>await Exec("insert into auth_session_events(id,session_id,user_id,organization_id,event_type,detail,actor) values(@event,@session,@user,@organization,@type,@detail,@actor)",c=>{Add(c,"event",Guid.NewGuid());Add(c,"session",session);Add(c,"user",user.Id);Add(c,"organization",user.OrganizationId??TenantDefaults.OrganizationId);Add(c,"type",type);Add(c,"detail",detail);Add(c,"actor",user.UserName);},t);private void Audit(string action,Guid id,AppUser user)=>db.AuditEvents.Add(new AuditEvent(Guid.NewGuid(),action,user.UserName,"AuthSession",id,DateTimeOffset.UtcNow,user.OrganizationId,user.BranchId));private AppUser? CurrentUser(){var sub=User.FindFirstValue(JwtRegisteredClaimNames.Sub)??User.FindFirstValue(ClaimTypes.NameIdentifier);return Guid.TryParse(sub,out var id)?db.AppUsers.SingleOrDefault(x=>x.Id==id&&x.IsActive):null;}private Guid? CurrentSession()=>Guid.TryParse(User.FindFirstValue("sid"),out var id)?id:null;private async Task<List<Dictionary<string,object?>>> Rows(string sql,Action<DbCommand> bind,CancellationToken t,Guid? current){await using var c=await Command(sql,t);bind(c);await using var r=await c.ExecuteReaderAsync(t);var rows=new List<Dictionary<string,object?>>();while(await r.ReadAsync(t)){var x=new Dictionary<string,object?>();for(var i=0;i<r.FieldCount;i++)x[Camel(r.GetName(i))]=r.IsDBNull(i)?null:r.GetValue(i);x["current"]=r.GetGuid(0)==current;rows.Add(x);}return rows;}private async Task<List<Guid>> Guids(string sql,Action<DbCommand> bind,CancellationToken t){await using var c=await Command(sql,t);bind(c);await using var r=await c.ExecuteReaderAsync(t);var l=new List<Guid>();while(await r.ReadAsync(t))l.Add(r.GetGuid(0));return l;}private async Task<int> Exec(string sql,Action<DbCommand> bind,CancellationToken t){await using var c=await Command(sql,t);bind(c);return await c.ExecuteNonQueryAsync(t);}private async Task<DbCommand> Command(string sql,CancellationToken t){var cn=db.Database.GetDbConnection();if(cn.State!=ConnectionState.Open)await cn.OpenAsync(t);var c=cn.CreateCommand();c.CommandText=sql;return c;}private static void Add(DbCommand c,string n,object? v){if(c.Parameters.Contains(n))return;var p=c.CreateParameter();p.ParameterName=n;p.Value=v??DBNull.Value;c.Parameters.Add(p);}private static string Camel(string v){var p=v.Split('_');return p[0]+string.Concat(p.Skip(1).Select(x=>char.ToUpperInvariant(x[0])+x[1..]));}
}public sealed record RevokeSessionRequest(string Reason);public sealed record RevokeAllSessionsRequest(string Reason,bool PreserveCurrent);
